update public.site_content set content = jsonb_set(content, '{features}', '[{"title":"1-on-1 Lessons","text":"Personalized for you","icon":"users"},{"title":"Flexible Schedule","text":"Book around your day","icon":"calendar"},{"title":"Secure Access","text":"Your account stays protected","icon":"shield"},{"title":"Progress Focused","text":"Learn with purpose","icon":"sparkles"}]'::jsonb, true) where page = 'home' and not (content ? 'features');
update public.site_content set content = jsonb_set(content, '{infoCards}', '[{"title":"Meaningful lessons","text":"Build skills with focused, teacher-led sessions.","icon":"book"},{"title":"Real availability","text":"See bookable teacher slots before you commit.","icon":"calendar"},{"title":"Human support","text":"Ask questions and stay connected when it matters.","icon":"message"},{"title":"A joyful rhythm","text":"Make learning easier to return to week after week.","icon":"sparkles"}]'::jsonb, true) where page = 'home' and not (content ? 'infoCards');
update public.site_content set content = jsonb_set(content, '{cards}', '[{"title":"Teacher first","text":"Give teachers a clean workspace to manage availability, subjects, and upcoming sessions.","icon":"graduation"},{"title":"Student centered","text":"Help students make confident choices about subjects, times, and lesson goals.","icon":"users"},{"title":"Trusted experience","text":"Keep sign-in and account access connected to secure Supabase authentication.","icon":"shield"}]'::jsonb, true) where page = 'about' and not (content ? 'cards');
update public.site_content set content = jsonb_set(content, '{steps}', '[{"title":"Choose a subject","text":"Find the lesson that matches your goal."},{"title":"Pick an open slot","text":"Book from teacher availability."},{"title":"Attend and learn","text":"Keep everything together in your workspace."}]'::jsonb, true) where page = 'schedule' and not (content ? 'steps');
update public.site_content set content = jsonb_set(jsonb_set(content, '{formTitle}', to_jsonb(coalesce(content->>'formTitle','Tell us what you need.')), true), '{contactIntro}', to_jsonb(coalesce(content->>'contactIntro','Use the form to send a message and our team will help with your next step.')), true) where page = 'contact';
